import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>照片上的文字只有让人读出来才有用。好看的说明文字淹没在复杂的背景里，还不如没有，因为它只会让观众着急。</p>\n<p>可读性不是品味问题。它来自对比度、大小、字体选择和位置，每一项都可以在发布前测试。</p>\n<p>这篇文章会讲清让图片文字可读的规则。包括字体、对比度、描边、背景板，以及能提前发现问题的测试习惯。想直接在图上加字试效果，<a href=\"/zh/tupian-tianjia-wenzi/\">图片添加文字</a>支持可拖动的样式文字，还能调字体、描边和阴影。</p>\n<h2 id=\"why-readability-matters\">可读性为什么比风格更重要</h2>\n<p>没人能读懂的时髦字体，就是失败的设计。图片文字的第一项工作是被读懂，风格只有在这项工作完成之后才有意义。</p>\n<p>大多数图片是在手机上看的，在信息流里，尺寸很小。电脑全尺寸下清晰的文字，在信息流预览里可能读不出来，那时图片只有几厘米宽。</p>\n<p>可读性还影响信任。文字清晰锐利的帖子看着专业，文字淡淡的、挤在一起的帖子看着粗心，哪怕照片本身很好。</p>\n<p>先测试可读性，再考虑风格。文字难读时，先修正对比度和大小，然后再操心哪种字体最好看。</p>\n<h2 id=\"contrast-ratio-basics\">对比度：最重要的一条规则</h2>\n<p>对比度是文字与背后背景之间的亮度差别。对比度高，字母清晰突出；对比度低，字母就融进去了。</p>\n<p>深色背景上的白色文字对比度高，浅色背景上的黑色文字也是。问题出在同一行文字背后既有亮区又有暗区的时候。</p>\n<p>整行文字都要检查对比度，不只检查某一个点。从深色阴影开始、到明亮天空结束的说明文字，一端可读、另一端就看不见了。</p>\n<p>背景变化时，给文字加描边、阴影或底框。这些效果能创造一个稳定的对比区域，照片本身提供不了这样的区域。</p>\n<h2 id=\"choosing-text-colour\">选择合适的文字颜色</h2>\n<p>白色是照片文字最安全的颜色，因为大多数照片都有够暗的区域让它可读，深色描边还能让它在明亮区域也好用。</p>\n<p>黑色适合明亮通透的照片，比如海滩、雪景和白墙。深色照片里黑色会消失在阴影里。</p>\n<p>黄色、红色或青色这样的亮色，适合简短的标题，长说明文字里更难读。强烈的颜色留给几个词。</p>\n<p>主文字一种颜色，强调最多再用第二种。混用太多颜色看着混乱，一致的搭配让设计保持干净可读。</p>\n<h2 id=\"choosing-background-areas\">把文字放在最平坦的区域</h2>\n<p>放文字最好的地方是照片最平坦的部分：晴朗的天空、空白的墙面、平静的海面，或者失焦的背景。平坦区域给字母留出呼吸的空间。</p>\n<p>不要把文字放在人脸、复杂图案或高对比细节上。眼睛没法把字母和底下的纹理分开，文字就很难读下去。</p>\n<p>放文字之前先看照片。平坦区域通常一眼就能找到，图层稍微挪一下，差别就很大。</p>\n<p>没有平坦区域时，把文字后面的区域调暗或模糊。半透明的覆盖层能创造一块平坦区域，又不完全遮住照片。</p>\n<h2 id=\"font-choice\">字体选择：可读优先于装饰</h2>\n<p>粗无衬线字体是照片文字可读性最高的字体。干净均匀的笔画在小尺寸和复杂背景上依然清晰，所以它是说明文字的默认选择。</p>\n<p>衬线字体适合婚礼照片和书封面这类正式图片。字母末端的小脚增加了优雅感，但小尺寸下可能模糊，所以要用大尺寸。</p>\n<p>手写体和装饰字体最难读。单个大词可以用，比如名字或标题，长说明文字完全不行。</p>\n<p>一张图片最多用一到两种字体。标题字体加说明字体就够了，再多会让设计看着杂乱、不专业。</p>\n<h2 id=\"font-size-rules\">字体大小：按最小的屏幕来定</h2>\n<p>文字大小是按图片百分比设置的，从2%到22%。标题需要接近范围上限的大尺寸，说明文字可以小一点。</p>\n<p>按文字会出现的最小屏幕定大小，不要按最大的屏幕定。电脑上清晰的说明文字，在手机信息流里图片显示小得多，可能读不出来。</p>\n<p>把导出后的图片缩小到信息流尺寸测试。在手机上缩小看一眼，不用放大就能读，才算过关。</p>\n<p>两个图层时，大小设得不一样。大标题加小说明文字，层次清晰，观众一下就知道先读什么。</p>\n<h2 id=\"line-length-and-spacing\">行长与间距</h2>\n<p>短行比长行容易读。横贯整张图片的说明文字很难跟读，居中在主体上的短行很容易扫读。</p>\n<p>在句子自然停顿的地方换行。短语中间换行感觉别扭，短语之间换行感觉是特意的、平静的。</p>\n<p>行与行之间留出空间。挤在一起的行会模糊成一片，尤其是在小尺寸下，留一点呼吸空间才能分清。</p>\n<p>文字总量保持简短。图片上几句选得好的词，效果远胜一段话；段落会遮住照片、压倒观众。</p>\n<h2 id=\"outlines-and-shadows\">描边与阴影</h2>\n<p>描边是在每个字母周围画一圈边框。白色文字加细细的深色描边，在明亮天空上也能读，这就是表情包用它的原因。</p>\n<p>阴影把文字从背景上托起来。它在字母后面加一道柔和的深色边缘，帮助文字脱颖而出，又没有描边那么硬。</p>\n<p>两者选其一，不要同时开到最强。描边加浓重阴影会让文字看着杂乱，单一效果更干净专业。</p>\n<p>经典表情包文字用白色字母加粗深色描边。这种组合在几乎任何背景上都可读，所以成了标准做法。</p>\n<h2 id=\"background-panels\">背景板与覆盖层</h2>\n<p>背景板是放在文字后面的半透明方框。深色底框让白色文字在任何地方都可读，浅色底框对深色文字也一样。</p>\n<p>底框是最可靠的可读性修复办法，因为它创造了一个稳定的背景，照片本身提供不了这样的背景。任何图片上都好用，不管多复杂。</p>\n<p>代价是遮盖面积。底框会遮住一部分照片，所以尽量按文字大小做，并放在最不重要的区域。</p>\n<p>全图覆盖层是更柔和的底框版本。整张照片稍微调暗，白色文字到处都可读，图片依然看得见。</p>\n<h2 id=\"text-over-busy-photos\">复杂照片上的文字</h2>\n<p>复杂的照片是可读性最难的情况。人群、森林或城市街道到处都是明暗区域，没有一种文字颜色能在所有地方都好用。</p>\n<p>先用描边或阴影，在每个字母周围创造局部的对比区域。不够的话，再在文字后面加底框。</p>\n<p>考虑把文字后面的区域模糊。轻柔的模糊能把复杂的背景变成平滑的色彩，文字读起来容易得多。</p>\n<p>照片复杂到任何办法都没用时，换一张照片。干净的图片加可读的文字，永远胜过复杂的图片加没人能读的文字。</p>\n<h2 id=\"text-over-faces\">文字不要盖在脸上</h2>\n<p>永远不要把文字放在人脸上。眼睛会先被脸吸引，横穿脸的文字和面部特征互相竞争，脸和文字都很难读。</p>\n<p>说明文字放在脸的下方或旁边，不要横穿它。下巴下面的说明文字或肩膀旁边的说明文字，容易读，又不碰脸。</p>\n<p>带引用的人像照，文字放在人物旁边的空白处。构图感觉自然，文字和脸各有自己的区域。</p>\n<p>人像占满整个画面时，底部用一块底框。底部一条深色横条给文字一个干净的位置，又不遮住脸。</p>\n<h2 id=\"hierarchy\">层次：标题、说明与署名</h2>\n<p>清晰的层次告诉观众先读什么。标题应该是最大最粗的文字，说明文字小一点，署名最小。</p>\n<p>用大小、粗细和颜色创造层次。大号粗标题加小号轻说明文字，一眼就清楚；三行同样大小的文字会互相竞争。</p>\n<p>层次最多三级。再多会让观众困惑，设计开始像表格，不像图片。</p>\n<p>位置也支持层次。顶部标题、底部说明是自然的阅读顺序，符合自上而下的阅读习惯，所以好用。</p>\n<h2 id=\"testing-small-screens\">在小屏幕上测试</h2>\n<p>大多数图片是在手机上看的，所以在手机上测试文字。导出图片，在手机上打开，不用放大就能读，才算过关。</p>\n<p>在信息流里检查，不要只看全屏。信息流预览把图片显示得小得多，全尺寸下清晰的文字，预览里可能就消失了。</p>\n<p>请别人读一读。新鲜的眼睛比制作者更快发现读不出来的文字，因为制作者早就知道上面写的是什么。</p>\n<p>不同光线下也要测试。明亮阳光下的手机屏幕会冲淡淡淡的文字，室内可读的说明文字，室外可能就读不出来了。</p>\n<h2 id=\"accessibility\">无障碍：让每个人都能读</h2>\n<p>好的可读性对所有人都有帮助，对视力不好的人尤其重要。高对比度、大尺寸、平坦背景，能让更多人读懂文字。</p>\n<p>不要只靠颜色传达意思。红色词和绿色词在色盲观众眼里可能一模一样，所以还要用大小或粗细区分。</p>\n<p>文字保持简短，语言保持简单。用词清楚的说明文字，比满是行话的聪明说明文字，能让更多读者读懂。</p>\n<p>分享图片时加替代文本。替代文本描述图片、重复说明文字，能帮助使用屏幕阅读器的人。</p>\n<h2 id=\"common-readability-mistakes\">常见的可读性错误</h2>\n<p>最常见的错误是文字太小。全尺寸看着好的说明文字，在社交信息流里图片显示小得多，可能读不出来。</p>\n<p>另一个错误是对比度差。明亮天空上的白色文字和深色背景上的黑色文字都会消失，所以要在实际照片上检查文字，不要在空白画布上检查。</p>\n<p>很多人还会用太多字体。一张图片上三四种字形看着混乱，单一一致的字体让设计保持干净专业。</p>\n<p>最后，不要把文字放在平台会裁掉的位置。社交应用会为不同屏幕修剪图片边缘，重要的词要放在框内足够靠里的位置。</p>\n<h2 id=\"readability-checklist\">发布前的可读性检查清单</h2>\n<p>检查整行文字的对比度。每个词都要可读，不只是前几个词，文字下面的背景不能中途变化。</p>\n<p>在手机信息流预览里检查大小。不用放大就读不出来的词，要调大尺寸或缩短文字。</p>\n<p>按实际使用的尺寸检查字体。放大了看着漂亮的装饰字体，缩到小尺寸可能读不出来。</p>\n<p>检查位置。文字应该放在平坦区域，远离人脸和边缘，周围留出足够的呼吸空间。</p>\n<p>实际操作步骤见<a href=\"/zh/blog/ruhe-zai-tupian-shang-jia-wenzi/\">如何在图片上加文字</a>，完整概览见<a href=\"/zh/blog/tupian-jia-wenzi-wanquan-zhinan/\">图片加文字完全指南</a>。想标记归属而不是加说明文字，可以用<a href=\"/zh/tianjia-shuiyin/\">图片水印工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"照片上的文字为什么难读？","answer":"主要原因是对比度低：明亮天空上的白色文字或深色背景上的黑色文字会消失。尺寸太小、背景复杂、装饰字体、文字盖在脸上，也会伤害可读性。先修正对比度和大小，再检查字体和位置。"},{"question":"照片文字应该用描边还是阴影？","answer":"两者任选其一，不要同时开到最强。明亮复杂的背景用深色描边围住白色文字效果最好，深色照片用柔和的阴影更合适。经典表情包文字用白色字母加粗深色描边。"},{"question":"手机信息流里的图片文字要多大？","answer":"大到在信息流里图片显示很小时，不用放大就能读。标题要用2%到22%范围里接近上限的尺寸。发布前在手机上按信息流尺寸看一眼导出后的图片。"},{"question":"照片上的文字放在哪里最好？","answer":"放在最平坦的区域，比如晴朗的天空、空白的墙面或平静的海面，远离人脸和边缘。平坦区域给字母留出呼吸的空间。没有平坦区域时，在文字后面加半透明的底框。"},{"question":"一张图片应该用几种字体？","answer":"最多一到两种：标题字体加说明字体。混用太多字形看着混乱、伤害可读性。单一一致的字体让设计保持干净，第二种字体只有在粗细或风格明显不同时才增加层次。"},{"question":"文字颜色对色盲观众有影响吗？","answer":"有。不要只靠颜色传达意思，因为红色和绿色在一些观众眼里可能一模一样。还要用大小、粗细和对比度区分，文字本身和背景保持高对比度。"}];
